    def sum_of_digits(num):
        total = 0
        for digit in str(abs(num)):
            total += int(digit)
        if num < 0:
            total -= int(str(abs(num))[0]) * 2  # Adjust for the signed digit
        return total

    count = 0
    for number in arr:
        if sum_of_digits(number) > 0:
            count += 1

    return count

